import{_ as a}from"./chunks/mmad_unitflag.BKsxOnwX.js";import{_ as n,o as p,a as c,b as l}from"./app.ejsEy6QV.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算","link":"/api/SIMD-API/c_api/cube_compute/cube_compute"},{"text":"矩阵计算关键特性说明","link":"/api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/mmad_compute_key_features"},{"text":"UnitFlag","link":"/api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/UnitFlag"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/UnitFlag.md","filePath":"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/UnitFlag.md","lastUpdated":1789544578000}'),_={name:"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/UnitFlag.md"};function e(t,s,m,i,o,d){return p(),c("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>UnitFlag</h1><p><strong>特性说明：</strong></p><p>unitFlag的核心功能体现为：asc_mmad和L0C Buffer搬出接口引入了单元标志（unit-flag）机制，通过以内存块为粒度实现精细化的数据同步，从而有效降低同步延迟，提升系统整体性能。当UnitFlag开关打开后，对于L0C Buffer中的内存块，硬件提供单元标志位指示该块是否可读或可写，内存块的具体大小由硬件行为控制，用户无需感知。</p><p>asc_mmad通过<code>asc_unit_flag_mode::ENABLE_KEEP</code>或<code>ENABLE_UPDATE</code>启用单元标志。</p><p>当<code>unit_flag_mode == asc_unit_flag_mode::ENABLE_KEEP</code>，开启unitFlag功能，在硬件执行完指令后，不改变单元标志位；</p><ul><li>对于写操作（asc_mmad接口），如果单元标志位0，则硬件直接写入L0C Buffer；否则，如果单元标志位为1，则写操作会等待直到单元标志变为0；执行完成后将单元标志位保持为0；</li><li>对于读操作（L0C Buffer搬出接口），如果单元标志位1，则硬件直接读取L0C Buffer；否则，如果单元标志位为0，则读操作会等待直到单元标志变为1；执行完成后将单元标志位保持为1；</li></ul><p>当<code>unit_flag_mode == asc_unit_flag_mode::ENABLE_UPDATE</code>，开启unitFlag功能，在硬件执行完指令后，改变单元标志位；</p><ul><li>对于写操作（asc_mmad接口），如果单元标志位0，则硬件直接写入L0C Buffer；否则，如果单元标志位为1，则写操作会等待直到单元标志变为0；执行完成后将单元标志位设置成1；</li><li>对于读操作（L0C Buffer搬出接口），如果单元标志位1，则硬件直接读取L0C Buffer；否则，如果单元标志位为0，则读操作会等待直到单元标志变为1；执行完成后将单元标志位设置成0；</li></ul><p>根据上述特性，如果用户在进行A矩阵[128, 1024]、B矩阵为[1024, 128]的矩阵乘计算时，需要沿着K轴进行迭代循环，假设每次迭代K长度为128，则需要迭代8次，此时8次asc_mmad对应1次搬出操作；</p><ul><li>前7次asc_mmad都设置成<code>asc_unit_flag_mode::ENABLE_KEEP</code>，写入后将单元标记位始终为0，保证后续asc_mmad可以写入L0C Buffer；</li><li>最后1次asc_mmad设置成<code>asc_unit_flag_mode::ENABLE_UPDATE</code>，写入后将单元标志位设置成1，保证Fixpipe可以读取L0C Buffer；</li><li>搬出接口设置为<code>asc_unit_flag_mode::ENABLE_UPDATE</code>，读取后将单元标记位设置为0，保证后续asc_mmad接口可以顺利写入L0C Buffer数据；</li></ul><p>如果用户需要单次asc_mmad的结果分多次搬出时，譬如asc_mmad计算结果的L0C Buffer为M(128) x N(256)，沿N轴分两次搬出；这样一次asc_mmad会对应两次搬出操作；</p><ul><li>asc_mmad的时候需要设置<code>asc_unit_flag_mode::ENABLE_UPDATE</code>，保证搬出时可以读取L0C Buffer数据；</li><li>每一次搬出接口都设置为<code>asc_unit_flag_mode::ENABLE_UPDATE</code>，读取后将单元标记位设置为0，保证后续其他asc_mmad接口在复用这块L0C Buffer地址时可以顺利写入数据；</li></ul><p>当开启unitFlag后，asc_mmad和L0C Buffer搬出接口会对同一块分形的L0C Buffer进行读写操作，因此asc_mmad计算和L0C Buffer搬出接口保持一致的读写顺序，有助于获得更优的性能表现。</p><p>在调用asc_mmad接口时，通过<a href="../asc_set_mmad_direction_m.html">asc_set_mmad_direction_m</a>或<a href="../asc_set_mmad_direction_n.html">asc_set_mmad_direction_n</a>配置计算方向，计算方向与推荐场景的具体说明请参考对应接口文档。</p><p><strong>图1</strong> asc_mmad和L0C Buffer搬出接口同时沿M方向写/读</p><p><img src="'+a+`" alt="asc_mmad和L0C Buffer搬出接口同时沿M方向写-读" title="asc_mmad和L0C Buffer搬出接口同时沿M方向写-读"></p><p><strong>特性约束：</strong></p><ul><li>asc_mmad和L0C Buffer搬出接口均提供了UnitFlag控制参数来控制该功能的启用，需确保两者同步开启，才能正常生效。</li><li>当希望控制同一块L0C Buffer内存空间能持续只被多条asc_mmad或多条搬出指令操作时，需将对应的前n-1条指令的unit_flag_mode设置为<code>asc_unit_flag_mode::ENABLE_KEEP</code>，维持被操作内存空间的持续占用状态，最后一条指令设置为<code>asc_unit_flag_mode::ENABLE_UPDATE</code>，解除被占用状态。</li><li>当启用unitFlag功能后，建议asc_mmad的计算数据量与搬出的数据量保持一致。若asc_mmad计算了大块数据（M × N = 128 × 128），但只搬出了其中一部分数据（M × N = 64 × 64），则可能会导致执行异常，可以通过<code>asc_set_l0c_copy_config</code>接口重置L0C Buffer的状态。</li></ul><p><strong>沿K轴迭代循环使用示例片段：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_set_mmad_direction_n</span><span class="p">();</span>
<span class="c1">// 调用k_round次asc_mmad</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">k_round</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 前k_round-1次迭代设置为ENABLE_KEEP，保证asc_mmad在K迭代循环中可以一直写入L0C Buffer</span>
<span class="w">    </span><span class="c1">// 最后一次迭代设置为ENABLE_UPDATE，保证asc_copy_l0c2gm可以读取L0C Buffer</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">flag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">k_round</span><span class="p">)</span>
<span class="w">        </span><span class="o">?</span><span class="w"> </span><span class="n">asc_unit_flag_mode</span><span class="o">::</span><span class="n">ENABLE_UPDATE</span>
<span class="w">        </span><span class="o">:</span><span class="w"> </span><span class="n">asc_unit_flag_mode</span><span class="o">::</span><span class="n">ENABLE_KEEP</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc_mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k_tile</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">flag</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="cm">/* 仅首次清零 */</span><span class="p">);</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">((</span><span class="n">m</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="p">(</span><span class="n">n</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">)</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">10</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_M</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="n">asc_set_l0c_copy_nz_para</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="n">asc_copy_l0c2gm</span><span class="p">(</span><span class="n">c_gm</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span>
<span class="w">    </span><span class="n">asc_store_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span>
<span class="w">    </span><span class="n">asc_unit_flag_mode</span><span class="o">::</span><span class="n">ENABLE_UPDATE</span><span class="p">,</span><span class="w"> </span><span class="n">asc_quant_mode</span><span class="o">::</span><span class="n">NoQuant</span><span class="p">,</span>
<span class="w">    </span><span class="n">asc_relu_pre_mode</span><span class="o">::</span><span class="n">NONE</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const w=n(_,[["render",e]]);export{r as __pageData,w as default};
